import { migrate as migratePglite } from "drizzle-orm/pglite/migrator";
import { migrate as migratePostgresJs } from "drizzle-orm/postgres-js/migrator";
import type { PgliteDatabase } from "drizzle-orm/pglite";
import type { PostgresJsDatabase } from "drizzle-orm/postgres-js";

import { getEnv } from "@/lib/env";
import { closeDb, createDb } from "./client";
import type * as schema from "./schema";

/**
 * Applies the SQL migrations in `drizzle/` (generated by `npm run
 * db:generate`) to whichever database `DATABASE_URL` points at. Run via
 * `npm run db:migrate`; assumes the working directory is the repo root (so
 * the relative `drizzle` migrations folder resolves correctly).
 */
async function main(): Promise<void> {
  const env = getEnv();
  const db = createDb(env.DATABASE_URL);

  if (env.DATABASE_URL.startsWith("pglite:")) {
    await migratePglite(db as PgliteDatabase<typeof schema>, { migrationsFolder: "drizzle" });
  } else {
    await migratePostgresJs(db as PostgresJsDatabase<typeof schema>, { migrationsFolder: "drizzle" });
  }

  await closeDb(db);
  console.log("Database migrations applied.");
}

main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});
